/**
  @file
  @brief Checks whether a file exists in SAS Drive
  @details Returns 1 if the file exists, and 0 if it doesn't.  Works by
  attempting to assign a fileref with the filesrvc engine.  When the file is
  not found the filename function sets syscc to a non zero value, so the macro
  resets syscc to zero and returns 0.

  A non zero syscc on entry means an earlier step has already failed.  The macro
  logs a %str(ERR)OR: line and returns 0 without touching syscc, so a caller
  comparing the result against 1 or 0 stays valid, and can tell this case from a
  genuine miss by checking syscc, which a miss resets to zero.

  Usage:

      %put %mfv_existfile(/does/exist.txt);
      %put %mfv_existfile(/does/not/exist.txt);

  @param [in] filepath The full path to the file on SAS drive
    (eg /Public/myfile.txt)

  <h4> SAS Macros </h4>
  @li mf_getuniquefileref.sas

  <h4> Related Macros </h4>
  @li mfv_existfolder.sas

  @version 3.5
  @author [Allan Bowe](https://www.linkedin.com/in/allanbowe/)
**/

%macro mfv_existfile(filepath
)/*/STORE SOURCE*/;

  %local fref rc path name;

  %if &syscc ne 0 %then %do;
    %put %str(ERR)OR: mfv_existfile.sas cannot execute with syscc=&syscc;
    0
    %return;
  %end;

  %let fref=%mf_getuniquefileref();
  %let name=%scan(&filepath,-1,/);
  %let path=%substr(&filepath,1,%length(&filepath)-%length(&name)-1);

  %if %sysfunc(filename(fref,,filesrvc,folderPath="&path" filename="&name"))=0
  %then %do;
    %sysfunc(fexist(&fref))
    %let rc=%sysfunc(filename(fref));
  %end;
  %else %do;
    0
    %let syscc=0;
  %end;

%mend mfv_existfile;

/**
  @file
  @brief Checks whether a folder exists in SAS Drive
  @details Returns 1 if the folder exists, and 0 if it doesn't.  Works by
  attempting to assign a fileref with the filesrvc engine.  When the folder is
  not found the filename function sets syscc to a non zero value, so the macro
  resets syscc to zero and returns 0.

  A non zero syscc on entry means an earlier step has already failed.  The macro
  logs a %str(ERR)OR: line and returns 0 without touching syscc, so a caller
  comparing the result against 1 or 0 stays valid, and can tell this case from a
  genuine miss by checking syscc, which a miss resets to zero.

  Usage:

      %put %mfv_existfolder(/does/exist);
      %put %mfv_existfolder(/does/not/exist);

  @param [in] path The path to the folder on SAS drive

  <h4> SAS Macros </h4>
  @li mf_getuniquefileref.sas

  <h4> Related Macros </h4>
  @li mfv_existfile.sas

  @version 3.5
  @author [Allan Bowe](https://www.linkedin.com/in/allanbowe/)
**/

%macro mfv_existfolder(path
)/*/STORE SOURCE*/;

  %local fref rc var;

  %if &syscc ne 0 %then %do;
    %put %str(ERR)OR: mfv_existfolder.sas cannot execute with syscc=&syscc;
    0
    %return;
  %end;

  %let fref=%mf_getuniquefileref();

  %if %sysfunc(filename(fref,,filesrvc,folderPath="&path"))=0 %then %do;
    1
    %let var=_FILESRVC_&fref._URI;
    %let rc=%sysfunc(filename(fref));
    %symdel &var;
  %end;
  %else %do;
    0
    %let syscc=0;
  %end;

%mend mfv_existfolder;

/**
  @file mfv_existsashdat.sas
  @brief Checks whether a CAS sashdat dataset exists in persistent storage.
  @details Can be used in open code, eg as follows:

      %if %mfv_existsashdat(libds=casuser.sometable) %then %put  yes it does!;

  The function uses `dosubl()` to run the `table.fileinfo` action, for the
  specified library, filtering for `*.sashdat` tables.

  Results are cached in a WORK table (&outprefix._&lib).  If that table
  already exists it is queried directly to avoid the dosubl() overhead.
  To force a rescan, use a new `&outprefix` value or delete the cache
  table before calling.

  @param [in] libds library.dataset
  @param [out] outprefix= (work.mfv_existsashdat)
    Used to store current HDATA tables to improve subsequent query performance.
    This reference is a prefix and is converted to `&prefix._{libref}`

  @return output returns 1 or 0

  @version 0.2
  @author Mathieu Blauw
**/

%macro mfv_existsashdat(libds,outprefix=work.mfv_existsashdat);
%local rc dsid name lib ds;
%let lib=%upcase(%scan(&libds,1,'.'));
%let ds=%upcase(%scan(&libds,-1,'.'));

/* if cache table does not exist, build it */
%if %sysfunc(exist(&outprefix._&lib)) ne 1 %then %do;
  %let rc=%sysfunc(dosubl(%nrstr(
    /* Read in table list (once per &lib per session) */
    proc cas;
      table.fileinfo result=source_list /caslib="&lib";
      val=findtable(source_list);
      saveresult val dataout=&outprefix._&lib;
    quit;
    /* Only keep name, without file extension */
    data &outprefix._&lib;
      set &outprefix._&lib(where=(upcase(Name) like '%.SASHDAT') keep=Name);
      Name=upcase(scan(Name,1,'.'));
    run;
  )));
%end;

/* Scan table for hdat existence */
%let dsid=%sysfunc(open(&outprefix._&lib(where=(name="&ds"))));
%syscall set(dsid);
%let rc = %sysfunc(fetch(&dsid));
%let rc = %sysfunc(close(&dsid));

/* Return result */
%if "%trim(&name)"="%trim(&ds)" %then 1;
%else 0;

%mend mfv_existsashdat;

/**
  @file mfv_getcaslib.sas
  @brief Returns the CAS caslib name for a given SAS libref
  @details Pure macro function.  Reads sashelp.vlibnam and returns
    the sysvalue where sysname='Caslib' for the given libref.  This
    is useful when the caslib name and libref name may differ.

    Usage:

        %put %mfv_getcaslib(lib=PUBLIC);

  @param [in] lib SAS libref for which to return the CAS caslib name

  @return Returns the CAS caslib name, or empty string if not found

**/

%macro mfv_getcaslib(lib);

%local dsid rc result;

%let dsid=%sysfunc(open(sashelp.vlibnam(
  where=(libname="%upcase(&lib)" and sysname="Caslib")
)));

%if &dsid %then %do;
  %let rc=%sysfunc(fetch(&dsid));
  %if &rc=0 %then
    %let result=%sysfunc(
      getvarc(&dsid,%sysfunc(varnum(&dsid,SYSVALUE)))
    );
  %let rc=%sysfunc(close(&dsid));
%end;

&result

%mend mfv_getcaslib;

/**
  @file
  @brief Returns the path of a folder from the URI
  @details Makes use of the SYSMSG() ER8OR response, which resolves the uri,
  seemingly without entering an er8or state.

  Usage:

      %mv_createfolder(path=/public/demo)
      %let uri=%mfv_getpathuri(/public/demo);
      %put %mfv_getfolderpath(&uri);

  Notice above the new path has an uppercase P - the correct path.

  @param [in] uri The uri of the folder -eg /folders/folders/xxxx)

  <h4> SAS Macros </h4>
  @li mf_getuniquefileref.sas

  <h4> Related Macros </h4>
  @li mfv_getpathuri.sas

  @version 4
  @author [Allan Bowe](https://www.linkedin.com/in/allanbowe/)
**/
%macro mfv_getfolderpath(uri
)/*/STORE SOURCE*/;

  %local fref rc path msg var /* var used to avoid delete timing issue */;
  %let fref=%mf_getuniquefileref();
  %if %quote(%substr(%str(&uri),1,17)) ne %quote(/folders/folders/)
  %then %do;
    %put &sysmacroname: Invalid URI: &uri;
  %end;
  %else %if %sysfunc(filename(fref,,filesrvc,folderuri="&uri" ))=0
  %then %do;
    %let var=_FILESRVC_&fref._URI;
    %local fid ;
    %let fid= %sysfunc(fopen(&fref,I));
    %let msg=%quote(%sysfunc(sysmsg()));

    %unquote(%scan(&msg,2,%str(,.)))

    %let rc=%sysfunc(fclose(&fid));
    %let rc=%sysfunc(filename(fref));
    %symdel &var;
  %end;
  %else %do;
    %put &sysmacroname: Not Found: &uri;
    %let syscc=0;
  %end;

%mend mfv_getfolderpath ;

/**
  @file
  @brief Returns the uri of a file or folder
  @details The automatic variable `_FILESRVC_[fref]_URI` is used after assigning
  a fileref using the filesrvc engine.  If the path does not exist the macro
  prints a note, returns nothing, and resets syscc to zero.

  A non zero syscc on entry means an earlier step has already failed.  The macro
  logs a %str(ERR)OR: line and returns an empty uri without touching syscc, so a
  caller that tests the uri for blankness sees no path, and the failure stays
  visible in syscc.

  Usage:

      %put %mfv_getpathuri(/Public/folder/file.txt);
      %put %mfv_getpathuri(/Public/folder);

  @param [in] filepath The full path to the file on SAS drive
    (eg /Public/myfile.txt)

  <h4> SAS Macros </h4>
  @li mf_getuniquefileref.sas

  <h4> Related Macros </h4>
  @li mfv_existfile.sas
  @li mfv_existfolder.sas

  @version 3.5
  @author [Allan Bowe](https://www.linkedin.com/in/allanbowe/)
**/

%macro mfv_getpathuri(filepath
)/*/STORE SOURCE*/;

  %local fref rc path name var /* var is used to avoid delete timing issue */;

  %if &syscc ne 0 %then %do;
    %put %str(ERR)OR: mfv_getpathuri.sas cannot execute with syscc=&syscc;
    %return;
  %end;

  %let fref=%mf_getuniquefileref();
  %let name=%scan(&filepath,-1,/);
  %let path=%substr(&filepath,1,%length(&filepath)-%length(&name)-1);

  %if %sysfunc(filename(fref,,filesrvc,folderPath="&path" filename="&name"))=0
  %then %do;
    %let var=_FILESRVC_&fref._URI;
    %str(&&&var)
    %let rc=%sysfunc(filename(fref));
    %symdel &var;
  %end;
  %else %do;
    %put &sysmacroname: did not find &filepath;
    %let syscc=0;
  %end;

%mend mfv_getpathuri;

/**
  @file mv_castabload.sas
  @brief Checks if a CAS table is loaded; if not, loads and promotes it
  @details Runs in SPRE against an active CAS session.  Accepts a
    SAS libref, derives the CAS caslib and session UUID from
    sashelp.vlibnam, then checks whether the table is already
    in-memory.  If not, locates the owning CAS server via the
    casManagement REST API, queries the table endpoint to discover
    the source file and caslib, then loads and promotes the table.

    A CAS session must already be established by the caller, eg:

        cas mysess;
        libname mylib cas caslib=Public;
        %mv_castabload(lib=mylib, table=BASEBALL)

  @param [in] lib=    SAS libref for the CAS caslib
  @param [in] table=  Name of the CAS table to load
  @param [in] mdebug= (0) Set to 1 to enable verbose logging:
                        - echoes resolved parameters
                        - prints tableExists result
                        - enables mprint/notes during PROC calls

  <h4> SAS Macros </h4>
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mf_getuniquelibref.sas
  @li mp_abort.sas

**/

%macro mv_castabload(
    lib=
    ,table=
    ,mdebug=0
);

%local _sysopts base_uri caslib uuid server
      srcfile srccaslib fname1 libref1 ftmp i _svcount _exists;
%let _sysopts=%sysfunc(getoption(mprint)) %sysfunc(getoption(notes));

/* ---- input validation -------------------------------------------------- */
%mp_abort(
  iftrue=("&lib"="" or "&table"=""),
  msg=%str(lib= and table= are required)
)

%if &mdebug=1 %then %do;
  %put &=lib;
  %put &=table;
  options mprint notes;
%end;

/* ---- derive caslib and session UUID from sashelp.vlibnam --------------- */
data _null_;
  set sashelp.vlibnam(
    where=(libname="%upcase(&lib)"
      and sysname in ("Caslib","Session UUID"))
  );
  if sysname="Caslib" then call symputx('caslib',sysvalue,'L');
  else call symputx('uuid',sysvalue,'L');
  %if &mdebug=1 %then %do;
    putlog sysname sysvalue;
  %end;
run;

%mp_abort(
  iftrue=("&caslib"=""),
  msg=%str(&lib is not an assigned CAS libref)
)

%mp_abort(
  iftrue=("&uuid"=""),
  msg=%str(No session UUID found for libref &lib)
)

/* ---- existence check --------------------------------------------------- */
proc cas;
  table.tableExists result=r /
      caslib="&caslib"
      name="&table";
  %if &mdebug=1 %then %do;
    print r;
  %end;
  if r.exists > 0 then call symputx('_exists', '1', 'L');
  else call symputx('_exists', '0', 'L');
quit;

/* ---- already loaded: skip ---------------------------------------------- */
%if &_exists=1 %then %do;
  %put NOTE: Table &caslib..&table already loaded - skipping;
  %return;
%end;

/* ---- get list of CAS servers ----------------------------------------- */
%let base_uri=%mf_getplatform(VIYARESTAPI);
%let fname1=%mf_getuniquefileref();
%let libref1=%mf_getuniquelibref();

proc http method='GET' out=&fname1 oauth_bearer=sas_services
    url="&base_uri/casManagement/servers";
run;

%mp_abort(
  iftrue=(&SYS_PROCHTTP_STATUS_CODE ne 200),
  msg=%str(&SYS_PROCHTTP_STATUS_CODE &SYS_PROCHTTP_STATUS_PHRASE)
)

libname &libref1 JSON fileref=&fname1;

data _null_;
  set &libref1..items;
  call symputx(cats('_sv_', _n_), name, 'L');
  call symputx('_svcount', _n_, 'L');
run;

libname &libref1 clear;
filename &fname1 clear;

/* ---- find which server owns this session ------------------------------ */
%do i=1 %to &_svcount;
  %if "&server"="" %then %do;
    %if &mdebug=1 %then %put checking server: &&_sv_&i;
    %let ftmp=%mf_getuniquefileref();
    proc http method='GET' out=&ftmp oauth_bearer=sas_services
      url="&base_uri/casManagement/servers/&&_sv_&i/sessions/&uuid";
    run;
    %if &SYS_PROCHTTP_STATUS_CODE=200
      %then %let server=&&_sv_&i;
    filename &ftmp clear;
  %end;
%end;

%mp_abort(
  iftrue=("&server"=""),
  msg=%str(Could not find owning server for CAS session &uuid)
)

%if &mdebug=1 %then %put &=server;

/* ---- discover source file from REST endpoint -------------------------- */
%let fname1=%mf_getuniquefileref();
%let libref1=%mf_getuniquelibref();

proc http method='GET' out=&fname1 oauth_bearer=sas_services
  url="&base_uri/casManagement/servers/&server/caslibs/&caslib/tables/&table";
run;

%if &mdebug=1 %then %do;
  %put &=SYS_PROCHTTP_STATUS_CODE &=SYS_PROCHTTP_STATUS_PHRASE;
  data _null_;
    infile &fname1;
    input;
    putlog _infile_;
  run;
%end;

%mp_abort(
  iftrue=(&SYS_PROCHTTP_STATUS_CODE=404),
  msg=%str(&caslib..&table not found - is a source file registered?)
)
%mp_abort(
  iftrue=(&SYS_PROCHTTP_STATUS_CODE ne 200),
  msg=%str(&SYS_PROCHTTP_STATUS_CODE &SYS_PROCHTTP_STATUS_PHRASE)
)

libname &libref1 JSON fileref=&fname1;

data _null_;
  set &libref1..tablereference;
  call symputx('srcfile', sourceTableName, 'L');
  call symputx('srccaslib', sourceCaslibName, 'L');
  stop;
run;

libname &libref1 clear;
filename &fname1 clear;

%mp_abort(
  iftrue=("&srcfile"="" or "&srccaslib"=""),
  msg=%str(No sourceTableName/sourceCaslibName for &caslib..&table)
)

%if &mdebug=1 %then %put &=srcfile &=srccaslib;

/* ---- load from discovered source -------------------------------------- */
proc casutil;
  load casdata="&srcfile"
      incaslib="&srccaslib"
      casout="&table"
      outcaslib="&caslib"
      promote;
quit;

%mp_abort(
  iftrue=(&syscc ne 0),
  msg=%str(Load failed for &caslib..&table)
)

%put NOTE: Table &caslib..&table loaded and promoted from &srcfile;

/* ---- restore options --------------------------------------------------- */
%if &mdebug=1 %then %do;
  options &_sysopts;
%end;

%mend mv_castabload;

/**
  @file mv_castabsave.sas
  @brief Saves an in-memory CAS table back to persistent storage
  @details Runs in SPRE against an active CAS session.  Accepts a
