/**
  @file mv_getclients.sas
  @brief Get a list of Viya Clients
  @details First, be sure you have an access token (which requires an app token).

  Using the macros here:

      filename mc url
        "https://raw.githubusercontent.com/sasjs/core/main/all.sas";
      %inc mc;

  An administrator needs to set you up with an access code:

      %mv_registerclient(outds=client)

  Navigate to the url from the log (opting in to the groups) and paste the
  access code below:

      %mv_tokenauth(inds=client,code=wKDZYTEPK6)

  Now we can run the macro!

      %mv_getclients()

  @param [out] outds= (work.mv_getclients)
    The library.dataset to be created that contains the list of clients


  @version VIYA V.03.04
  @author Allan Bowe, source: https://github.com/sasjs/core

  <h4> SAS Macros </h4>
  @li mp_abort.sas
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mf_getuniquelibref.sas
  @li mf_loc.sas

  @sasjslint {"maxLineLength": 102}
**/

%macro mv_getclients(outds=work.mv_getclients
)/*/STORE SOURCE*/;

options noquotelenmax;
%local base_uri; /* location of rest apis */
%let base_uri=%mf_getplatform(VIYARESTAPI);

/* first, get consul token needed to get client id / secret */
data _null_;
  infile "%mf_loc(VIYACONFIG)/etc/SASSecurityCertificateFramework/tokens/consul/default/client.token";
  input token:$64.;
  call symputx('consul_token',token);
run;

/* request the client details */
%local fname1;
%let fname1=%mf_getuniquefileref();
proc http method='POST' out=&fname1
    url="&base_uri/SASLogon/oauth/clients/consul?callback=false%str(&)serviceId=app";
    headers "X-Consul-Token"="&consul_token";
run;

%local libref1;
%let libref1=%mf_getuniquelibref();
libname &libref1 JSON fileref=&fname1;

/* extract the token */
data _null_;
  set &libref1..root;
  call symputx('access_token',access_token,'l');
run;

/* fetching folder details for provided path */
%local fname2;
%let fname2=%mf_getuniquefileref();
%let libref2=%mf_getuniquelibref();

proc http method='GET' out=&fname2 oauth_bearer=sas_services
  url="&base_uri/SASLogon/oauth/clients";
  headers "Accept"="application/json";
run;
/*data _null_;infile &fname1;input;putlog _infile_;run;*/
%mp_abort(iftrue=(&SYS_PROCHTTP_STATUS_CODE ne 200)
  ,mac=&sysmacroname
  ,msg=%str(&SYS_PROCHTTP_STATUS_CODE &SYS_PROCHTTP_STATUS_PHRASE)
)
libname &libref2 JSON fileref=&fname1;

data &outds;
  set &libref2..items;
run;



/* clear refs
filename &fname1 clear;
libname &libref1 clear;
*/
%mend mv_getclients;

/**
  @file
  @brief Gets a list of folder members (and ids) for a given root
  @details Returns all members for a particular Viya folder.  Works at both root
  level and below, and results are created in an output dataset.

        %mv_getfoldermembers(root=/Public, outds=work.mymembers)

  A root with nothing to list - an empty folder, or an answer that carries no
  members link - still yields &outds, with the documented columns and zero rows.


  @param [in] root= (/) The path for which to return the list of folders
  @param [out] outds= (work.mv_getfolders) The output dataset to create. Format:
  |ordinal_root|ordinal_items|creationTimeStamp| modifiedTimeStamp|createdBy|modifiedBy|id| uri|added| type|name|description|
  |---|---|---|---|---|---|---|---|---|---|---|---|
  |1|1|2021-05-25T11:15:04.204Z|2021-05-25T11:15:04.204Z|allbow|allbow|4f1e3945-9655-462b-90f2-c31534b3ca47|/folders/folders/ed701ff3-77e8-468d-a4f5-8c43dec0fd9e|2021-05-25T11:15:04.212Z|child|my_folder_name|My folder Description|

  @param [in] access_token_var= (ACCESS_TOKEN) The global macro variable to
    contain the access token
  @param [in] grant_type= (sas_services) Valid values are:
    @li password
    @li authorization_code
    @li detect
    @li sas_services

  @version VIYA V.03.04
  @author Allan Bowe, source: https://github.com/sasjs/core

  <h4> SAS Macros </h4>
  @li mp_abort.sas
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mf_getuniquelibref.sas
  @li mf_isblank.sas

  <h4> Related Macros </h4>
  @li mv_createfolder.sas
  @li mv_deletefoldermember.sas
  @li mv_deleteviyafolder.sas
  @li mv_getfoldermembers.test.sas

  @sasjslint {"maxLineLength": 230}
**/

%macro mv_getfoldermembers(root=/
    ,access_token_var=ACCESS_TOKEN
    ,grant_type=sas_services
    ,outds=mv_getfolders
  );
%local oauth_bearer;
%if &grant_type=detect %then %do;
  %if %symexist(&access_token_var) %then %let grant_type=authorization_code;
  %else %let grant_type=sas_services;
%end;
%if &grant_type=sas_services %then %do;
    %let oauth_bearer=oauth_bearer=sas_services;
    %let &access_token_var=;
%end;

%mp_abort(iftrue=(&grant_type ne authorization_code and &grant_type ne password
    and &grant_type ne sas_services
  )
  ,mac=&sysmacroname
  ,msg=%str(Invalid value for grant_type: &grant_type)
)

%if %mf_isblank(&root)=1 %then %let root=/;

options noquotelenmax;

/* request the client details */
%local fname1 libref1;
%let fname1=%mf_getuniquefileref();
%let libref1=%mf_getuniquelibref();

%local base_uri; /* location of rest apis */
%let base_uri=%mf_getplatform(VIYARESTAPI);

%if "&root"="/" %then %do;
  /* if root just list root folders */
  proc http method='GET' out=&fname1 &oauth_bearer
      url="&base_uri/folders/rootFolders?limit=1000";
  %if &grant_type=authorization_code %then %do;
      headers "Authorization"="Bearer &&&access_token_var";
  %end;
  run;
  libname &libref1 JSON fileref=&fname1;
  /* an empty collection produces no items dataset at all, so a straight SET
    would fail with "File ...ITEMS.DATA does not exist" and leave syscc dirty */
  %if %sysfunc(exist(&libref1..items))=1 %then %do;
    data &outds;
      /* the documented columns are declared on every path, so a caller reads
        the same columns whether the collection is empty or full - an empty
        collection's items dataset carries a narrower shape (no createdBy,
        no timestamps) than a populated one.  The declared lengths are at
        least the engine's own, which are sized to the payload */
      length ordinal_root 8 ordinal_items 8
        creationTimeStamp $32 modifiedTimeStamp $32
        createdBy $64 modifiedBy $64
        id $36 uri $512 added $32 type $32
        name $256 description $256;
      /* initialise the declared columns - an empty collection's items
        dataset carries none of the member columns, and referencing one that
        the input does not supply raises "Variable x is uninitialized" */
      call missing(of _all_);
      set &libref1..items;
      /* the engine emits one all-missing row for an empty collection */
      if missing(name) and missing(uri) then delete;
    run;
  %end;
  %else %do;
    %put NOTE: &sysmacroname - no root folders found;
    data &outds;
      length ordinal_root 8 ordinal_items 8
        creationTimeStamp $32 modifiedTimeStamp $32
        createdBy $64 modifiedBy $64
        id $36 uri $512 added $32 type $32
        name $256 description $256;
      call missing(of _all_);
      stop;
    run;
  %end;
%end;
%else %do;
  /* first get parent folder id */
  proc http method='GET' out=&fname1 &oauth_bearer
      url="&base_uri/folders/folders/@item?path=&root";
  %if &grant_type=authorization_code %then %do;
      headers "Authorization"="Bearer &&&access_token_var";
  %end;
  run;
  /*data _null_;infile &fname1;input;putlog _infile_;run;*/
  libname &libref1 JSON fileref=&fname1;
  /* now get the followon link to list members */
  %local href cnt;
  %let cnt=0;
  /* a root that is not a folder (a member path, for instance) answers
    without a links dataset, so a straight SET would leave syscc dirty */
  %if %sysfunc(exist(&libref1..links))=1 %then %do;
    data _null_;
      length rel href $512;
      call missing(rel,href);
      set &libref1..links;
      if rel='members' then do;
        url=cats("'","&base_uri",href,"?limit=10000'");
        call symputx('href',url,'l');
        call symputx('cnt',1,'l');
      end;
    run;
  %end;
  %if &cnt=0 %then %do;
    %put NOTE:;%put NOTE-  No members found in &root!!;%put NOTE-;
    /* the folder answered without a members link, so there is nothing to list -
      the output dataset is still created, with the documented columns */
    data &outds;
      length ordinal_root 8 ordinal_items 8
        creationTimeStamp $32 modifiedTimeStamp $32
        createdBy $64 modifiedBy $64
        id $36 uri $512 added $32 type $32
        name $256 description $256;
      call missing(of _all_);
      stop;
    run;
    filename &fname1 clear;
    libname &libref1 clear;
    %return;
  %end;
  %local fname2 libref2;
  %let fname2=%mf_getuniquefileref();
  %let libref2=%mf_getuniquelibref();
  proc http method='GET' out=&fname2 &oauth_bearer
      url=%unquote(%superq(href));
  %if &grant_type=authorization_code %then %do;
      headers "Authorization"="Bearer &&&access_token_var";
  %end;
  run;
  libname &libref2 JSON fileref=&fname2;
  /* an emptied folder produces no items dataset at all, so a straight SET would
    fail with "File ...ITEMS.DATA does not exist" and leave syscc dirty */
  %if %sysfunc(exist(&libref2..items))=1 %then %do;
    data &outds;
      length ordinal_root 8 ordinal_items 8
        creationTimeStamp $32 modifiedTimeStamp $32
        createdBy $64 modifiedBy $64
        id $36 uri $512 added $32 type $32
        name $256 description $256;
      /* initialise the declared columns - an empty collection's items
        dataset carries none of the member columns, and referencing one that
        the input does not supply raises "Variable x is uninitialized" */
      call missing(of _all_);
      set &libref2..items;
      /* the engine emits one all-missing row for an empty collection */
      if missing(name) and missing(uri) then delete;
    run;
  %end;
  %else %do;
    %put NOTE: &sysmacroname - &root is empty;
    data &outds;
      length ordinal_root 8 ordinal_items 8
        creationTimeStamp $32 modifiedTimeStamp $32
        createdBy $64 modifiedBy $64
        id $36 uri $512 added $32 type $32
        name $256 description $256;
      call missing(of _all_);
      stop;
    run;
  %end;
  filename &fname2 clear;
  libname &libref2 clear;
%end;


/* clear refs */
filename &fname1 clear;
libname &libref1 clear;

%mend mv_getfoldermembers;

/**
  @file mv_getgroupmembers.sas
  @brief Creates a dataset with a list of group members
  @details First, be sure you have an access token (which requires an app token)

  Using the macros here:

      filename mc url
        "https://raw.githubusercontent.com/sasjs/core/main/all.sas";
      %inc mc;

  Now we can run the macro!

      %mv_getgroupmembers(All Users)

  outputs:

      ordinal_root num,
      ordinal_items num,
      version num,
      id char(256),
      name char(256),
      providerId char(32),
      implicit num,
      type char(32)

  `type` is the member type (user or group) and is declared on every path.
  `implicit` is declared so a caller reading it does not fail with "Variable
  implicit not found", but the identities API returns no such field, so the
  column is present and always missing.  A group with no members, and a group
  id the server does not know, both return the columns above with zero rows.

  @param [in] group Group id for which to return group members
  @param [in] access_token_var= (ACCESS_TOKEN)
    The global macro variable to contain the access token
  @param [in] grant_type= (sas_services)
    valid values are "password" or "authorization_code" (unquoted).
  @param [out] outds= (work.viyagroupmembers)
    The library.dataset to be created that contains the list of members

  id and name are declared at $256, the longest active directory can hold for
  a display name or a SAM account name.  The $43 they used to carry truncated
  anything longer, and a truncation fails the step on some platforms.


  @version VIYA V.03.04
  @author Allan Bowe, source: https://github.com/sasjs/core

  <h4> SAS Macros </h4>
  @li mp_abort.sas
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mf_getuniquelibref.sas
  @li mf_existvar.sas

**/

%macro mv_getgroupmembers(group
    ,access_token_var=ACCESS_TOKEN
    ,grant_type=sas_services
    ,outds=work.viyagroupmembers
  );
%local oauth_bearer;
%if &grant_type=detect %then %do;
  %if %symexist(&access_token_var) %then %let grant_type=authorization_code;
  %else %let grant_type=sas_services;
%end;
%if &grant_type=sas_services %then %do;
    %let oauth_bearer=oauth_bearer=sas_services;
    %let &access_token_var=;
%end;

%mp_abort(iftrue=(&grant_type ne authorization_code and &grant_type ne password
    and &grant_type ne sas_services
  )
  ,mac=&sysmacroname
  ,msg=%str(Invalid value for grant_type: &grant_type)
)

options noquotelenmax;

%local base_uri; /* location of rest apis */
%let base_uri=%mf_getplatform(VIYARESTAPI);

/* fetching folder details for provided path */
%local fname1;
%let fname1=%mf_getuniquefileref();
proc http method='GET' out=&fname1 &oauth_bearer
  url="&base_uri/identities/groups/&group/members?limit=10000";
  headers
  %if &grant_type=authorization_code %then %do;
          "Authorization"="Bearer &&&access_token_var"
  %end;
          "Accept"="application/json";
run;
/*data _null_;infile &fname1;input;putlog _infile_;run;*/
%if &SYS_PROCHTTP_STATUS_CODE=404 %then %do;
  %put NOTE:  Group &group not found!!;
  /* the same documented columns and zero rows as a group with no members -
    call missing alone would output one all-missing observation */
  data &outds;
    length ordinal_root 8 ordinal_items 8 version 8
      id $256 name $256 providerId $32 implicit 8 type $32;
    call missing(of _all_);
    stop;
  run;
%end;
%else %do;
  %mp_abort(iftrue=(&SYS_PROCHTTP_STATUS_CODE ne 200)
    ,mac=&sysmacroname
    ,msg=%str(&SYS_PROCHTTP_STATUS_CODE &SYS_PROCHTTP_STATUS_PHRASE)
  )
  %let libref1=%mf_getuniquelibref();
  libname &libref1 JSON fileref=&fname1;
  /* a group with no members returns a collection whose items dataset carries no
    member columns, so a straight SET would raise "Variable id is uninitialized"
    and leave syscc dirty.  Only copy when there is something to copy.  The
    documented columns are declared on both paths, so an empty group hands the
    caller the same PDV as a populated one.  The lengths are declared because
    the JSON engine sizes its columns to the longest value in the payload:
    $256 is the longest an active directory display name or SAM account name
    can hold, and a shorter declaration lets the engine report "Multiple
    lengths were specified" on a later member. */
  %local itemsds hasvars;
  %let itemsds=&libref1..items;
  %let hasvars=0;
  %if %sysfunc(exist(&itemsds))=1 %then %do;
    %if %mf_existvar(&itemsds,id)>0 %then %let hasvars=1;
  %end;
  data &outds;
    length ordinal_root 8 ordinal_items 8 version 8
      id $256 name $256 providerId $32 implicit 8 type $32;
    call missing(of _all_);
    %if &hasvars=1 %then %do;
      set &itemsds;
      /* the engine emits one all-missing row for an empty collection */
      if missing(id) then delete;
    %end;
    %else %do;
      stop;
    %end;
  run;
  libname &libref1 clear;
%end;

/* clear refs */
filename &fname1 clear;

%mend mv_getgroupmembers;

